/* Vintage Paper Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="vintage-paper-light"] {
  --background: rgb(247, 242, 227);
  --foreground: rgb(74, 64, 55);
  --card: rgb(255, 252, 244);
  --card-foreground: rgb(74, 64, 55);
  --popover: rgb(255, 252, 244);
  --popover-foreground: rgb(74, 64, 55);
  --primary: rgb(168, 124, 81);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(224, 214, 194);
  --secondary-foreground: rgb(92, 77, 63);
  --muted: rgb(235, 228, 214);
  --muted-foreground: rgb(126, 107, 85);
  --accent: rgb(210, 199, 170);
  --accent-foreground: rgb(74, 64, 55);
  --destructive: rgb(180, 76, 56);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(218, 208, 187);
  --input: rgb(218, 208, 187);
  --ring: rgb(168, 124, 81);
  --chart-1: rgb(168, 124, 81);
  --chart-2: rgb(140, 110, 78);
  --chart-3: rgb(117, 91, 57);
  --chart-4: rgb(179, 145, 113);
  --chart-5: rgb(194, 161, 128);
  --radius: 0.25rem;
  --sidebar: rgb(235, 228, 214);
  --sidebar-foreground: rgb(74, 64, 55);
  --sidebar-primary: rgb(168, 124, 81);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(210, 199, 170);
  --sidebar-accent-foreground: rgb(74, 64, 55);
  --sidebar-border: rgb(218, 208, 187);
  --sidebar-ring: rgb(168, 124, 81);
  --font-sans: Libre Baskerville, serif;
  --font-serif: Lora, serif;
  --font-mono: IBM Plex Mono, monospace;
  --shadow-color: rgb(58, 51, 44);
  --shadow-opacity: 0.12;
  --shadow-blur: 5px;
  --shadow-spread: 0px;
  --shadow-offset-x: 2px;
  --shadow-offset-y: 3px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 2px 3px 5px 0px hsl(28 13% 20% / 0.06);
  --shadow-xs: 2px 3px 5px 0px hsl(28 13% 20% / 0.06);
  --shadow-sm:
    2px 3px 5px 0px hsl(28 13% 20% / 0.12),
    2px 1px 2px -1px hsl(28 13% 20% / 0.12);
  --shadow:
    2px 3px 5px 0px hsl(28 13% 20% / 0.12),
    2px 1px 2px -1px hsl(28 13% 20% / 0.12);
  --shadow-md:
    2px 3px 5px 0px hsl(28 13% 20% / 0.12),
    2px 2px 4px -1px hsl(28 13% 20% / 0.12);
  --shadow-lg:
    2px 3px 5px 0px hsl(28 13% 20% / 0.12),
    2px 4px 6px -1px hsl(28 13% 20% / 0.12);
  --shadow-xl:
    2px 3px 5px 0px hsl(28 13% 20% / 0.12),
    2px 8px 10px -1px hsl(28 13% 20% / 0.12);
  --shadow-2xl: 2px 3px 5px 0px hsl(28 13% 20% / 0.3);
  --tracking-normal: 0em;
}

