  --foreground: rgb(235, 228, 214);
  --card: rgb(59, 49, 41);
  --card-foreground: rgb(235, 228, 214);
  --popover: rgb(59, 49, 41);
  --popover-foreground: rgb(235, 228, 214);
  --primary: rgb(194, 161, 128);
  --primary-foreground: rgb(42, 37, 34);
  --secondary: rgb(75, 64, 56);
  --secondary-foreground: rgb(235, 228, 214);
  --muted: rgb(59, 49, 41);
  --muted-foreground: rgb(196, 189, 176);
  --accent: rgb(90, 73, 61);
  --accent-foreground: rgb(235, 228, 214);
  --destructive: rgb(180, 76, 56);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(75, 64, 56);
  --input: rgb(75, 64, 56);
  --ring: rgb(194, 161, 128);
  --chart-1: rgb(194, 161, 128);
  --chart-2: rgb(179, 145, 113);
  --chart-3: rgb(168, 124, 81);
  --chart-4: rgb(140, 110, 78);
  --chart-5: rgb(117, 91, 57);
  --radius: 0.25rem;
  --sidebar: rgb(42, 37, 34);
  --sidebar-foreground: rgb(235, 228, 214);
  --sidebar-primary: rgb(194, 161, 128);
  --sidebar-primary-foreground: rgb(42, 37, 34);
  --sidebar-accent: rgb(90, 73, 61);
  --sidebar-accent-foreground: rgb(235, 228, 214);
  --sidebar-border: rgb(75, 64, 56);
  --sidebar-ring: rgb(194, 161, 128);
  --font-sans: Libre Baskerville, serif;
  --font-serif: Lora, serif;
  --font-mono: IBM Plex Mono, monospace;
  --shadow-color: rgb(58, 51, 44);
  --shadow-opacity: 0.12;
  --shadow-blur: 5px;
  --shadow-spread: 0px;
  --shadow-offset-x: 2px;
  --shadow-offset-y: 3px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 2px 3px 5px 0px hsl(28 13% 20% / 0.06);
  --shadow-xs: 2px 3px 5px 0px hsl(28 13% 20% / 0.06);
  --shadow-sm:
    2px 3px 5px 0px hsl(28 13% 20% / 0.12),
